const root=ref(null),stage=ref(0),reduced=ref(false);
let timer,observer,motion,visible=false;
function stop(){clearTimeout(timer);}
function advance(){stop();if(!visible||document.hidden||reduced.value)return;timer=setTimeout(()=>{stage.value=(stage.value+1)%4;advance();},stage.value===3?5200:3200);}
