onMounted(()=>{motion=window.matchMedia('(prefers-reduced-motion: reduce)');reduced.value=motion.matches;if(reduced.value)stage.value=3;motion.addEventListener('change',onMotion);document.addEventListener('visibilitychange',sync);if('IntersectionObserver' in window){observer=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;advance();},{threshold:.2});observer.observe(root.value);}else{visible=true;advance();}});
function onMotion(event){reduced.value=event.matches;stage.value=event.matches?3:0;advance();}
onBeforeUnmount(()=>{stop();observer?.disconnect();motion?.removeEventListener('change',onMotion);document.removeEventListener('visibilitychange',sync);});
</script>
